from itertools import combinations

def subfamily_separates(phi, J):
    '''Check if subfamily J separates all states.'''
    n = len(phi[0])
    phi_J = [phi[j] for j in J]
    for x in range(n):
        for y in range(x + 1, n):
            if all(phi_J[k][x] == phi_J[k][y] for k in range(len(J))):
                return False
    return True

def compute_separation_rank(phi):
    '''Compute the separation rank and a minimal separating subfamily.'''
    num_obs = len(phi)
    for k in range(1, num_obs + 1):
        for J in combinations(range(num_obs), k):
            if subfamily_separates(phi, list(J)):
                return k, list(J)
    return num_obs, list(range(num_obs))

# Example
phi = [
    [0, 0, 1, 1],  # Observer 0
    [0, 1, 0, 1],  # Observer 1
    [0, 0, 1, 1],  # Observer 2 (duplicate)
    [0, 1, 0, 1],  # Observer 3 (duplicate)
]
rank, J = compute_separation_rank(phi)
print(f"Separation rank: {rank}, minimal subfamily: {J}")

def tropical_distance(phi, x, y):
    '''Compute tropical separation distance d_Φ(x, y) = max_i |Φ_i(x) - Φ_i(y)|.'''
    return max(abs(phi[i][x] - phi[i][y]) for i in range(len(phi)))

def tropical_distance_matrix(phi):
    '''Compute the full pairwise tropical distance matrix.'''
    n = len(phi[0])
    return [[tropical_distance(phi, x, y) for y in range(n)] for x in range(n)]

# Example
phi = [[1, 3, 2, 5, 4], [2, 2, 4, 1, 3], [0, 1, 1, 2, 0]]
D = tropical_distance_matrix(phi)
print("Distance matrix:")
for row in D:
    print(row)

def find_spectral_witness(phi, J, i):
    '''Find a spectral witness for observer i in subfamily J.'''
    n = len(phi[0])
    J_minus_i = [j for j in J if j != i]
    for x in range(n):
        for y in range(x + 1, n):
            others_agree = all(phi[j][x] == phi[j][y] for j in J_minus_i)
            i_disagrees = phi[i][x] != phi[i][y]
            if others_agree and i_disagrees:
                return (x, y)
    return None

# Example
phi = [[0, 0, 1, 1], [0, 1, 0, 1]]
J = [0, 1]
for i in J:
    w = find_spectral_witness(phi, J, i)
    print(f"Observer {i}: spectral witness = {w}")
